function pushMatch(
  matches: RawMatch[],
  start: number,
  end: number,
  isAssignmentValue = false,
): void {
  matches.push({
    start,
    end,
    category: 'secret',
    priority: isAssignmentValue ? PRIORITY.secretAssignment : PRIORITY.secret,
    isAssignmentValue,
  })
}

